import{_ as t,o,c as a,ah as r}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Core modules","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/core-modules.md","filePath":"src/en/guide/core-modules.md"}'),n={name:"en/guide/core-modules.md"};function i(s,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="core-modules" tabindex="-1">Core modules <a class="header-anchor" href="#core-modules" aria-label="Permalink to &quot;Core modules&quot;">​</a></h1><p>Modules 1 to 18, 29 and 32 form the core. This page summarises the rules that shape day-to-day work; the exhaustive detail lives in the reference documentation.</p><h2 id="catalogue-module-1" tabindex="-1">Catalogue (module 1) <a class="header-anchor" href="#catalogue-module-1" aria-label="Permalink to &quot;Catalogue (module 1)&quot;">​</a></h2><p>A <strong>programme</strong> is a training course in the catalogue, identified by a stable, immutable code <code>NB.XX.YY</code>. The prefix follows the category:</p><table tabindex="0"><thead><tr><th>Category</th><th>Code</th><th>Duration</th></tr></thead><tbody><tr><td>Career Paths</td><td><code>NB.FP.01</code> – <code>NB.FP.10</code></td><td>500 h / 25 weeks + internship (700 h for the Web &amp; Mobile Development package)</td></tr><tr><td>Business Skills</td><td><code>NB.CM.01</code> – <code>NB.CM.12</code></td><td>250 h / 12 weeks + internship</td></tr><tr><td>Technologies &amp; Tools</td><td><code>NB.TO.01</code> – <code>NB.TO.18</code></td><td>250 h / 12 weeks + internship</td></tr></tbody></table><p>Three statuses: <strong>draft</strong>, <strong>published</strong>, <strong>archived</strong>. Only a published programme is visible on the website. Unpublishing is impossible while it is linked to an open, confirmed or running cohort.</p><p>The price is never entered freely: it derives from the category and the format, through the price grid.</p><table tabindex="0"><thead><tr><th>Category</th><th>Online</th><th>Hybrid</th><th>In person</th></tr></thead><tbody><tr><td>Career Paths</td><td>850,000</td><td>900,000</td><td>950,000</td></tr><tr><td>Web &amp; Mobile Development</td><td>1,000,000</td><td>1,100,000</td><td>1,150,000</td></tr><tr><td>Business Skills / Technologies &amp; Tools</td><td>450,000</td><td>500,000</td><td>550,000</td></tr></tbody></table><p>Amounts in FCFA, excluding tax. A price change is scheduled from a date and only applies to cohorts opened afterwards.</p><p>A programme&#39;s <strong>QCM bank</strong> holds 20 validated questions. Import uses an <code>.xlsx</code> workbook, one tab per programme, followed by an explicit validation: importing and validating are two distinct actions. The imported file is never kept.</p><h2 id="cohorts-module-2" tabindex="-1">Cohorts (module 2) <a class="header-anchor" href="#cohorts-module-2" aria-label="Permalink to &quot;Cohorts (module 2)&quot;">​</a></h2><p>A cohort is a session of a programme, attached to a yearly <strong>promotion</strong>:</p><table tabindex="0"><thead><tr><th>Promotion</th><th>Intake</th></tr></thead><tbody><tr><td>Baobab</td><td>September</td></tr><tr><td>Iroko</td><td>December</td></tr><tr><td>Acacia</td><td>March</td></tr><tr><td>Karité</td><td>June</td></tr></tbody></table><p>Opening conditions: published programme, validated QCM bank, a price for every proposed format, at least one Lead Trainer assigned. Maximum capacity: <strong>15 learners</strong>. Grid prices are frozen when the cohort opens.</p><p>Statuses: <strong>open</strong>, <strong>confirmed</strong>, <strong>in progress</strong>, <strong>completed</strong>, <strong>postponed</strong>, <strong>cancelled</strong>.</p><ul><li>The Coordinator confirms an open cohort.</li><li>A confirmed cohort starts on its start date on its own; a running cohort completes on its own after its end date.</li><li>Postponement and cancellation are only possible before the start, require a reason, and are final.</li><li>A cohort mixes the three formats: format and price are carried by each enrolment.</li></ul><p>The <strong>profitability zone</strong> is recalculated on every confirmed enrolment or withdrawal:</p><table tabindex="0"><thead><tr><th>Confirmed headcount</th><th>Zone</th></tr></thead><tbody><tr><td>Fewer than 7</td><td>Fragile</td></tr><tr><td>7 to 11</td><td>Viable</td></tr><tr><td>12 to 15</td><td>Comfortable</td></tr></tbody></table><p>The Viable and Comfortable thresholds are configurable per category. A cohort freezes its zone and headcount when it starts: threshold changes only affect future cohorts.</p><p>The <strong>profitability dashboard</strong> (module 13) shows, for open and confirmed cohorts, the zone, headcount, signed and pending revenue, staffing cost and its coverage. A Fragile cohort less than a week from starting is flagged “to decide”; nothing happens automatically.</p><h2 id="candidatures-and-admission-module-18" tabindex="-1">Candidatures and admission (module 18) <a class="header-anchor" href="#candidatures-and-admission-module-18" aria-label="Permalink to &quot;Candidatures and admission (module 18)&quot;">​</a></h2><p>Four strictly sequential steps: <strong>submission</strong>, <strong>interview</strong>, <strong>test</strong>, <strong>decision</strong>.</p><ul><li>Interview within 5 business days, closed by the responsible advisor.</li><li>Test: single-use link, 48 hours to start, 2 attempts of 45 minutes, 10 questions out of 20, indicative 60% pass mark.</li><li>Reasoned decision within 3 business days.</li><li>One candidature in progress per account; resubmission possible 7 days after a refusal.</li><li>Refused candidature kept 12 months, then anonymised: statistics remain, personal data disappears.</li></ul><p>The full flow is described in <a href="/kura-guide/en/guide/learner-journey.html">Learner journey</a>.</p><h2 id="enrolments-and-consents-module-3" tabindex="-1">Enrolments and consents (module 3) <a class="header-anchor" href="#enrolments-and-consents-module-3" aria-label="Permalink to &quot;Enrolments and consents (module 3)&quot;">​</a></h2><p>The enrolment is created on admission, with the status <strong>pending signature</strong>. Statuses: <code>pending_signature</code>, <code>active</code>, <code>suspended</code>, <code>dropped</code>, <code>completed</code>.</p><ul><li>Any non-dropped enrolment holds a seat; headcount and zone only count signed enrolments.</li><li>The format can be changed until signature, among the formats priced for the cohort.</li><li>Two separate consents are required before signature: pedagogical reuse of the tutored project and image rights. Every change is logged.</li><li>For a minor, only the legal representative&#39;s consents count, collected through a single-use 7-day email link.</li><li><strong>Shared funding</strong> designates an organisation account with the Funder role and its share (1 to 100%), frozen in the agreement.</li></ul><h2 id="attendance-module-4" tabindex="-1">Attendance (module 4) <a class="header-anchor" href="#attendance-module-4" aria-label="Permalink to &quot;Attendance (module 4)&quot;">​</a></h2><ul><li>Virtual sessions are read every hour from <code>mod_attendance</code> and cannot be edited in Kura.</li><li>An in-person session is entered by a Lead Trainer of the cohort or by the Coordinator, once held.</li><li>Lateness counts as attendance; an excused absence counts as an absence.</li><li>Absence rate = missed minutes ÷ programme hours. The alert fires <strong>once</strong> above 30%, and re-arms if a correction brings it back below the threshold.</li></ul><h2 id="results-module-5" tabindex="-1">Results (module 5) <a class="header-anchor" href="#results-module-5" aria-label="Permalink to &quot;Results (module 5)&quot;">​</a></h2><ul><li>Per-block grades flow back from Sève through the <code>KURA-BLOC-{id}</code> code, out of 20.</li><li>Average weighted by block duration, recalculated on every read.</li><li>A block is validated at 10/20, compensable from 8 to 10, eliminatory below 8. The retained grade is the last graded attempt.</li><li>Retake opened by a Lead Trainer or the Coordinator: block below 10/20, 15 days after the last grade, at most twice. It is filled by the first Sève grade given after opening.</li><li>Jury entered by the Coordinator: tutored project, defence, internship. These grades stay <strong>out of the average</strong>; the internship does not block the certificate.</li></ul><h2 id="certification-module-6" tabindex="-1">Certification (module 6) <a class="header-anchor" href="#certification-module-6" aria-label="Permalink to &quot;Certification (module 6)&quot;">​</a></h2><p>The certificate requires <strong>four cumulative conditions</strong>:</p><ol><li>average ≥ 10/20;</li><li>no block below 8/20;</li><li>defence validated;</li><li>balance fully paid.</li></ol><p>None compensates another. The certificate is delivered once by the Coordinator, in the name of the jury president, as a sealed PDF. Mentions: Passable from 10/20, then Assez bien, Bien and Très bien according to configurable thresholds (12, 14 and 16 by default).</p><p>Delivery completes the enrolment, removes the learner from their cohort course, moves the account to the <strong>Canopé</strong> status and enrols it in Parcours Canopé.</p><p>A <strong>partial attestation</strong> is reserved for a dropped enrolment with at least one validated block. A <strong>transcript of competences</strong> accompanies the certificate or attestation.</p><h2 id="communication-module-8" tabindex="-1">Communication (module 8) <a class="header-anchor" href="#communication-module-8" aria-label="Permalink to &quot;Communication (module 8)&quot;">​</a></h2><ul><li>Announcements from the Coordinator or Administrator to one cohort, or to all cohorts of a programme.</li><li>Recipients: pending, active or suspended enrolments, and by default assigned trainers and coaches.</li><li>Channels: email and Sève, sent immediately. No WhatsApp for announcements.</li><li>Every delivery is logged, channel by channel, with its status and error.</li></ul><h2 id="reporting-and-direction-modules-9-and-15" tabindex="-1">Reporting and Direction (modules 9 and 15) <a class="header-anchor" href="#reporting-and-direction-modules-9-and-15" aria-label="Permalink to &quot;Reporting and Direction (modules 9 and 15)&quot;">​</a></h2><p>Both views are <strong>read-only</strong>, over the same period and with the same definitions.</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Reporting</th><th>Direction</th></tr></thead><tbody><tr><td>Fill rate, success, attestations</td><td>Yes</td><td>Yes</td></tr><tr><td>Invoiced, collected, outstanding</td><td>Yes</td><td>Yes</td></tr><tr><td>Attendance, overall average</td><td>Yes</td><td>Yes</td></tr><tr><td>Paid out and gross margin</td><td>No</td><td>Yes</td></tr><tr><td>L&#39;Éclosion portfolio</td><td>No</td><td>Yes</td></tr></tbody></table><p>Reporting exports the cohort list as CSV (semicolon, UTF-8 with BOM, in the user&#39;s language).</p><h2 id="remuneration-and-commissions-modules-10-to-12" tabindex="-1">Remuneration and commissions (modules 10 to 12) <a class="header-anchor" href="#remuneration-and-commissions-modules-10-to-12" aria-label="Permalink to &quot;Remuneration and commissions (modules 10 to 12)&quot;">​</a></h2><ul><li><strong>Trainers and coaches</strong>: hourly rate by zone, project flat fee, coach flat fee per learner, external jury token. The grid is configurable and each rate takes effect on a date. A cohort keeps the rates and zone of its start.</li><li><strong>Business referrers</strong>: 5% of amounts collected, instalment by instalment, including the funder&#39;s share. A refund reverses the commission with a negative line.</li><li><strong>Marketing partners</strong>: paid on invoice submission, within the contract or campaign flat fee; reasoned validation or rejection by the Coordinator.</li></ul><p>The calculation and payout details are in <a href="/kura-guide/en/guide/billing.html#remuneration-and-commissions">Billing</a>.</p>',46)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
